# AnyKernel3 Template for Nothing Phone 2 (Pong)

# This template is adapted from osm0sis/AnyKernel3 for Pong-specific flashing.
# DO NOT edit this file directly — it's a template for scripts/package-anykernel3.sh

DEVICE_CODENAME="pong"
DEVICE_MODEL="SM8475"
BOOT_PARTITION="boot"  # Pong uses boot.img (NOT init_boot.img!)
IS_SIDEPART=0
IS_PHASED=1

# Flash commands for Pong
# The updater-script in META-INF/com/google/android/ is generated by package-anykernel3.sh

# IMPORTANT: Pong has A/B slots — always flash to the correct slot
# In recovery: use slot_a or slot_b based on current active slot
# In Fastboot: flash boot_<slot> where <slot> is a or b
